using System;
using System.Text;
using System.Threading.Tasks;
using Garnet.cluster;
using Microsoft.Extensions.Logging;
using Xunit;

namespace Garnet.Tests.cluster
{
    public class ReplicationManagerTests
    {
        [Fact]
        public async Task TryReplicateDiskbasedSyncAsync_ReturnsFalseOnException()
        {
            // Arrange
            var replicationManager = new ReplicationManager();

            // Act
            var result = await replicationManager.TryReplicateDiskbasedSyncAsync(null, null);

            // Assert
            Assert.False(result.Success);
            Assert.True(result.ErrorMessage.Length > 0 || result.ErrorMessage.IsEmpty == false);
        }
    }
}
